import{d as p,C as a,o as d,c as g,a3 as s,E as e,j as n,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十八章","description":"《正易心法》第二十八章——乾坤六子，其象与数：象上坤加乾画生三男、乾加坤画生三女；数上乾三巽离兑四震坎艮五坤六，坤六震坎艮七巽离兑八乾九；乾坤在外，六子包于其中。","frontmatter":{"title":"正易心法·第二十八章","description":"《正易心法》第二十八章——乾坤六子，其象与数：象上坤加乾画生三男、乾加坤画生三女；数上乾三巽离兑四震坎艮五坤六，坤六震坎艮七巽离兑八乾九；乾坤在外，六子包于其中。","category":"guide","aliases":["正易心法第二十八章","乾坤六子其象与数","乾坤之位皆包六子"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-28.md","filePath":"yijing/zheng-yi-xin-fa/chapter-28.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-28.md"},x=p({...c,setup(b){const o=[{id:"z28-01",label:"一、其象与数",showLabel:!0,sentences:[["乾坤六子，其",{text:"象与数",glossary:"xiangYuShu"},"。乾坤之位，皆包六子。"]],note:["乾坤与六子的关系，要从象和数两个角度来看：乾坤的位置（范围），都包含了六子在其中。（**本章从第十九章「入位生六子」再进一步**：第九章说六子怎么生，本章说从象、数两方面都能看出「乾坤包六子」——**乾坤是边界，六子在中间。**）"]},{id:"z28-02",label:"二、象上包六子",showLabel:!0,sentences:[["象谓坤卦上中下加三乾画，便生",{text:"三男",glossary:"sannan"},"。以乾卦上中下加三坤画，便生",{text:"三女",glossary:"sannv"},"。"]],note:["从象来说：坤卦的上、中、下三个位置，分别加入一根阳爻，就生出了三男（震、坎、艮）；以乾卦的上、中、下三个位置，分别加入一根阴爻，就生出了三女（巽、离、兑）。（**这是第九章「破体」的列表式重述**：坤体被破三次得三男（阳少阴多），乾体被破三次得三女（阴少阳多）——**六子都是「二与一」的比例，唯乾坤是「纯」。**）"]},{id:"z28-03",label:"三、象上乾坤在外",showLabel:!0,sentences:[["乾坤之体，皆在外，六子皆包于其中也。"]],note:["乾坤的卦体处于两端，六子都包含在其中。（**「在外」是空间关系**：乾坤＝纯阳／纯阴＝两端／边界，六子＝混杂＝中间／内部。**这就在象上印证了第二十章「乾坤真体、六子假合」：真体包含假合，边界生成中间。**）"]},{id:"z28-04",label:"四、数上包六子",showLabel:!0,sentences:[["数谓若画乾数三，巽离兑四，震坎艮五，坤六。坤数六，震坎艮七，巽离兑八，乾九。"]],note:["从数来说：画乾卦，数为三；巽、离、兑各为四；震、坎、艮各为五；坤卦为六。反过来，坤数为六，震、坎、艮各为七，巽、离、兑各为八，乾为九。（**计数方式是「阳爻一画、阴爻两画」**：乾＝3×1＝3；巽离兑＝2×1＋1×2＝4；震坎艮＝1×1＋2×2＝5；坤＝3×2＝6。**反向从坤起：每加一阳爻加一**，故坤6、震坎艮7、巽离兑8、乾9。**坤（6）成了两组数列的中心对称点。**）"]},{id:"z28-05",label:"五、象之自然",showLabel:!0,sentences:[["乾坤之策皆在外，六子皆包于其中也。此象之自然，有不可得而",{text:"容心",glossary:"rongxin"},"者。"]],note:["乾坤的策数处于两端，六子都包含在其中。这是卦象的自然规律，有不可以用人为安排来解释的自然性。（**「容心」是宋人口语，意为「用心思去安排、干预」**。麻衣三章连说「非容心」：第二十四章「羲皇画卦，非出私意」、第二十六章「气序自然」、本章「象之自然，有不可得而容心者」——**《易》的一切结构都是自然之理的自然呈现，「容心」恰恰是理解《易》的最大障碍。**）"]}],r=[{id:"xiangYuShu",term:"其象与数",pinyin:"qí xiàng yǔ shù",meaning:"从象（卦画结构）和数（爻画数量）两个角度来看。"},{id:"sannan",term:"三男",pinyin:"sān nán",meaning:"震（长男）、坎（中男）、艮（少男）——坤体被一阳所破而生。"},{id:"sannv",term:"三女",pinyin:"sān nǚ",meaning:"巽（长女）、离（中女）、兑（少女）——乾体被一阴所破而生。"},{id:"rongxin",term:"容心",pinyin:"róng xīn",meaning:"用心思去安排、干预。「不可得而容心」即不可以人为安排解释。"}];return(u,t)=>{const i=a("DaoTextReading"),l=a("DaoKeywordCards");return d(),g("div",null,[t[0]||(t[0]=s("",24)),e(i,{colophon:"其象与数 · 乾坤在外 · 六子包中 · 不可容心",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十八章原文",sections:o,glossary:r}),t[1]||(t[1]=n("blockquote",null,[n("p",null,"注：本页依所据底本录入，用字随底本，不作统一。本章「数」按「阳爻一画、阴爻两画」的计法，读者可自行核对。")],-1)),t[2]||(t[2]=n("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),n("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(l,{items:[{term:"其象与数",pinyin:["xiàng","shù"],meaning:"从象（卦画结构）与数（爻画数量）两方面论证同一结论——双向印证，故非凑巧亦非人为。"},{term:"三男三女",pinyin:["sān","nán"],meaning:"坤加一阳生震坎艮（三男），乾加一阴生巽离兑（三女）——六子皆是「二与一」的比例。"},{term:"乾坤在外",pinyin:["qián","kūn"],meaning:"象上：乾坤是纯体，处在两端；数上：乾3/9、坤6，也在两端。六子皆包于其中。"},{term:"策数序列",pinyin:["cè","shù"],meaning:"乾3、巽离兑4、震坎艮5、坤6；坤6、震坎艮7、巽离兑8、乾9。坤（6）是中心对称点。"},{term:"不可得而容心",pinyin:["róng","xīn"],meaning:"「容心」＝用心思去安排。三章连说「非容心」，是麻衣反对人为解释的核心立场。"}]}),t[3]||(t[3]=s("",26))])}}});export{y as __pageData,x as default};
